// Evaluate source health based on response
const sourceId = $('Fetch All Active Sources').item.json.id;
const sourceName = $('Fetch All Active Sources').item.json.name;
const sourceUrl = $('Fetch All Active Sources').item.json.url;
const sourceType = $('Fetch All Active Sources').item.json.source_type;
const consecutiveFailures = $('Fetch All Active Sources').item.json.consecutive_failures || 0;

let statusCode = null;
let responseTime = null;
let isHealthy = false;
let errorMessage = null;
let feedValid = false;

const response = $json;

if (response.error) {
  // Request failed
  isHealthy = false;
  errorMessage = response.error.message || 'Connection failed';
} else {
  statusCode = response.statusCode || 200;
  responseTime = response.headers && response.headers['x-response-time'] 
    ? parseInt(response.headers['x-response-time']) 
    : null;

  isHealthy = statusCode >= 200 && statusCode < 400;

  // Validate RSS feed structure if it's an RSS source
  if (sourceType === 'rss' && response.body) {
    feedValid = response.body.includes('<rss') || 
                response.body.includes('<feed') || 
                response.body.includes('<channel');
    if (!feedValid) {
      isHealthy = false;
      errorMessage = 'Invalid RSS feed structure';
    }
  }
}

const newConsecutiveFailures = isHealthy ? 0 : consecutiveFailures + 1;

return [{
  json: {
    source_id: sourceId,
    source_name: sourceName,
    source_url: sourceUrl,
    source_type: sourceType,
    is_healthy: isHealthy,
    status_code: statusCode,
    response_time_ms: responseTime,
    feed_valid: feedValid,
    error_message: errorMessage,
    consecutive_failures: newConsecutiveFailures,
    checked_at: new Date().toISOString(),
    should_alert: newConsecutiveFailures >= 3
  }
}];

